import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

/** Shape of public/ff01-campus-3d.json (generated by scripts/build_campus_3d.py). */
export type XZ = [number, number];
export interface PolygonXZ { o: XZ[]; h: XZ[][] }
export type RoomKind =
  | 'classroom' | 'lab' | 'creative' | 'library' | 'dining' | 'meeting'
  | 'hall' | 'office' | 'service' | 'room';

export interface CampusModelRoom {
  id: string;
  name: string;
  nameSource: string;
  kind: RoomKind;
  series: string;
  areaM2Label: number | null;
  areaM2Polygon: number | null;
  label: XZ;
  polygon: PolygonXZ | null;
  geometryStatus: string;
}

interface PackedSegments { count: number; int16cm: string }

export interface CampusModelData {
  modelID: string;
  status: string;
  statement: string;
  heights: { wallM: number; seatRowRiseM: number; seatBaseM: number; measured: boolean };
  bounds: [number, number, number, number];
  footprint: { polygon: PolygonXZ; status: string };
  walls: PolygonXZ[];
  glazing: PolygonXZ[];
  rooms: CampusModelRoom[];
  corridors: Array<{ id: string; polygon: PolygonXZ }>;
  arena: { court: XZ[][]; seats: Array<{ p: XZ[]; row: number }>; standBlocks: PolygonXZ[]; seatCount: number };
  floorLines: Record<'furniture' | 'doors' | 'stairs' | 'court', PackedSegments>;
}

export const CAMPUS_MODEL_URL = '/ff01-campus-3d.json';

export async function loadCampusModel(signal?: AbortSignal): Promise<CampusModelData> {
  const response = await fetch(CAMPUS_MODEL_URL, { signal });
  if (!response.ok) throw new Error(`Campus model request failed: ${response.status}`);
  return response.json();
}

/**
 * Room palette. `calm` is the everyday lunar tint; `strong` is used by the 空间 layer
 * so categories separate clearly. Orange is never used here: it marks selection and life.
 */
export const ROOM_KIND_STYLE: Record<RoomKind, { calm: number; strong: number; label: string }> = {
  classroom: { calm: 0xd6e1ec, strong: 0x9dbad6, label: '教室与书院' },
  lab: { calm: 0xcbe3e0, strong: 0x86c2bb, label: '实验与科创' },
  creative: { calm: 0xe5daed, strong: 0xc4a6d2, label: '艺术与创作' },
  library: { calm: 0xd9dcf1, strong: 0xa8afe0, label: '图书与阅读' },
  dining: { calm: 0xede2c6, strong: 0xe2c983, label: '餐厅' },
  meeting: { calm: 0xd8e7d1, strong: 0xa5cd96, label: '会议与研讨' },
  hall: { calm: 0xe9dbd0, strong: 0xd9b7a4, label: '多功能与活动' },
  office: { calm: 0xdde2e8, strong: 0xb5bdc9, label: '办公与服务' },
  service: { calm: 0xd2d7de, strong: 0xa0a8b4, label: '库房与设备' },
  room: { calm: 0xdce0e5, strong: 0xc2c8d0, label: '其他房间' },
};

const COLORS = {
  ground: 0xdde2e7,
  slab: 0xf6f7f8,
  slabEdge: 0xc3cad3,
  wallSide: 0xf8f9fb,
  wallCap: 0x2a3342,
  glass: 0x9cc2d9,
  court: 0xdacdb6,
  courtLines: 0xffffff,
  furniture: 0x98a2b0,
  doors: 0x9aa6b6,
  stairs: 0x8892a3,
  seatLow: new THREE.Color(0xd35400),
  seatHigh: new THREE.Color(0xfdcb9c),
  stand: 0xe8ebef,
  selected: 0xff7a00,
  hovered: 0xffe1c4,
};

function toShape(poly: PolygonXZ): THREE.Shape {
  // Shapes are authored in (x, -z) so rotateX(-PI/2) maps them onto the XZ ground with +Y up.
  const shape = new THREE.Shape(poly.o.map(([x, z]) => new THREE.Vector2(x, -z)));
  for (const hole of poly.h) shape.holes.push(new THREE.Path(hole.map(([x, z]) => new THREE.Vector2(x, -z))));
  return shape;
}

function extrude(poly: PolygonXZ, height: number, base = 0): THREE.BufferGeometry {
  const geometry = new THREE.ExtrudeGeometry(toShape(poly), { depth: height, bevelEnabled: false, curveSegments: 1 });
  geometry.rotateX(-Math.PI / 2);
  if (base) geometry.translate(0, base, 0);
  return geometry;
}

function flat(poly: PolygonXZ, y: number): THREE.BufferGeometry {
  const geometry = new THREE.ShapeGeometry(toShape(poly), 1);
  geometry.rotateX(-Math.PI / 2);
  geometry.translate(0, y, 0);
  return geometry;
}

function decodeSegments(packed: PackedSegments, y: number): THREE.BufferGeometry {
  const bytes = Uint8Array.from(atob(packed.int16cm), (c) => c.charCodeAt(0));
  const values = new Int16Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 2);
  const positions = new Float32Array(packed.count * 6);
  for (let i = 0; i < packed.count; i += 1) {
    positions[i * 6] = values[i * 4] / 100;
    positions[i * 6 + 1] = y;
    positions[i * 6 + 2] = values[i * 4 + 1] / 100;
    positions[i * 6 + 3] = values[i * 4 + 2] / 100;
    positions[i * 6 + 4] = y;
    positions[i * 6 + 5] = values[i * 4 + 3] / 100;
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  return geometry;
}

function mergeAll(geometries: THREE.BufferGeometry[]): THREE.BufferGeometry {
  const prepared = geometries.map((g) => (g.index ? g.toNonIndexed() : g));
  prepared.forEach((g) => g.clearGroups());
  const merged = mergeGeometries(prepared, false) ?? new THREE.BufferGeometry();
  geometries.forEach((g) => g.dispose());
  prepared.forEach((g) => g.dispose());
  return merged;
}

/** Slice a geometry's draw range [start, start+count) into a standalone non-indexed geometry. */
function sliceGeometry(geometry: THREE.BufferGeometry, start: number, count: number): THREE.BufferGeometry {
  const source = geometry.index ? geometry.toNonIndexed() : geometry;
  const out = new THREE.BufferGeometry();
  for (const name of Object.keys(source.attributes)) {
    const attr = source.getAttribute(name) as THREE.BufferAttribute;
    const array = attr.array.slice(start * attr.itemSize, (start + count) * attr.itemSize);
    out.setAttribute(name, new THREE.BufferAttribute(array, attr.itemSize, attr.normalized));
  }
  if (source !== geometry) source.dispose();
  return out;
}

/**
 * Merge extrusions while keeping two material groups: 0 = caps (top/bottom), 1 = sides.
 * ExtrudeGeometry emits exactly these two groups per shape.
 */
function mergeCapsAndSides(geometries: THREE.BufferGeometry[]): THREE.BufferGeometry {
  const caps: THREE.BufferGeometry[] = [];
  const sides: THREE.BufferGeometry[] = [];
  for (const g of geometries) {
    for (const group of g.groups) (group.materialIndex === 0 ? caps : sides).push(sliceGeometry(g, group.start, group.count));
    g.dispose();
  }
  const capGeometry = mergeAll(caps);
  const sideGeometry = mergeAll(sides);
  const merged = mergeGeometries([capGeometry, sideGeometry], true) ?? new THREE.BufferGeometry();
  capGeometry.dispose();
  sideGeometry.dispose();
  return merged;
}

export interface CampusScene {
  root: THREE.Group;
  roomMeshes: Map<string, THREE.Mesh>;
  roomById: Map<string, CampusModelRoom>;
  pickables: THREE.Object3D[];
  wallTopY: number;
  setRoomColors: (colorFor: (room: CampusModelRoom) => number) => void;
  setHighlight: (selectedId: string | null, hoveredId: string | null) => void;
  setDetailVisible: (visible: boolean) => void;
  /** Advances colour transitions; returns true while something is still animating. */
  tick: (dtMs: number) => boolean;
  dispose: () => void;
}

export function buildCampusScene(model: CampusModelData): CampusScene {
  const root = new THREE.Group();
  root.name = 'FF-01 campus 3D model (source-derived, unverified)';
  const H = model.heights.wallM;

  // Site ground around the building.
  const [minX, minZ, maxX, maxZ] = model.bounds;
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(4000, 4000),
    new THREE.ShadowMaterial({ color: 0x18202e, opacity: 0.1 }),
  );
  ground.rotation.x = -Math.PI / 2;
  ground.position.set((minX + maxX) / 2, -0.32, (minZ + maxZ) / 2);
  ground.receiveShadow = true;
  root.add(ground);

  // Floor slab from the derived footprint.
  const slab = new THREE.Mesh(extrude(model.footprint.polygon, 0.3, -0.3), [
    new THREE.MeshLambertMaterial({ color: COLORS.slab }),
    new THREE.MeshLambertMaterial({ color: COLORS.slabEdge }),
  ]);
  slab.receiveShadow = true;
  slab.name = 'Floor slab (derived footprint)';
  root.add(slab);

  // Rooms: one mesh each so they can be picked and recoloured.
  const roomMeshes = new Map<string, THREE.Mesh>();
  const roomById = new Map<string, CampusModelRoom>();
  const roomGroup = new THREE.Group();
  roomGroup.name = 'Rooms';
  for (const room of model.rooms) {
    roomById.set(room.id, room);
    if (!room.polygon) continue;
    const material = new THREE.MeshLambertMaterial({ color: ROOM_KIND_STYLE[room.kind].calm, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -1 });
    const mesh = new THREE.Mesh(flat(room.polygon, 0.015), material);
    mesh.receiveShadow = true;
    mesh.userData.roomId = room.id;
    mesh.userData.baseColor = ROOM_KIND_STYLE[room.kind].calm;
    roomMeshes.set(room.id, mesh);
    roomGroup.add(mesh);
  }
  for (const corridor of model.corridors) {
    if (!corridor.polygon) continue;
    const mesh = new THREE.Mesh(flat(corridor.polygon, 0.01), new THREE.MeshLambertMaterial({ color: 0xf1ece2 }));
    mesh.receiveShadow = true;
    roomGroup.add(mesh);
  }
  root.add(roomGroup);

  // Arena: court surface, stand base and tiered seats.
  const arena = new THREE.Group();
  arena.name = 'Lotus Arena';
  const courtGeometries = model.arena.court.map((ring) => flat({ o: ring, h: [] }, 0.02));
  const court = new THREE.Mesh(mergeAll(courtGeometries), new THREE.MeshLambertMaterial({ color: COLORS.court, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 }));
  court.receiveShadow = true;
  arena.add(court);
  const standBase = new THREE.Mesh(
    mergeAll(model.arena.standBlocks.map((p) => extrude(p, model.heights.seatBaseM * 0.6))),
    new THREE.MeshLambertMaterial({ color: COLORS.stand }),
  );
  standBase.castShadow = true;
  standBase.receiveShadow = true;
  arena.add(standBase);
  const maxRow = Math.max(1, ...model.arena.seats.map((s) => s.row));
  const seatGeometries = model.arena.seats.map((seat) => {
    const h = model.heights.seatBaseM + seat.row * model.heights.seatRowRiseM;
    const g = extrude({ o: seat.p, h: [] }, h);
    const c = COLORS.seatLow.clone().lerp(COLORS.seatHigh, seat.row / maxRow);
    const colors = new Float32Array(g.getAttribute('position').count * 3);
    for (let i = 0; i < colors.length; i += 3) { colors[i] = c.r; colors[i + 1] = c.g; colors[i + 2] = c.b; }
    g.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    g.clearGroups();
    return g;
  });
  const seats = new THREE.Mesh(mergeAll(seatGeometries), new THREE.MeshLambertMaterial({ vertexColors: true }));
  seats.castShadow = true;
  seats.receiveShadow = true;
  arena.add(seats);
  root.add(arena);

  // Floor detail lines from furniture, doors, stairs and court markings.
  const detail = new THREE.Group();
  detail.name = 'Floor detail lines';
  const lineLayer = (key: keyof CampusModelData['floorLines'], color: number, opacity: number, y: number) => {
    const lines = new THREE.LineSegments(
      decodeSegments(model.floorLines[key], y),
      new THREE.LineBasicMaterial({ color, transparent: true, opacity, depthWrite: false }),
    );
    lines.renderOrder = 2;
    detail.add(lines);
  };
  lineLayer('furniture', COLORS.furniture, 0.45, 0.04);
  lineLayer('stairs', COLORS.stairs, 0.8, 0.05);
  lineLayer('doors', COLORS.doors, 0.7, 0.05);
  lineLayer('court', COLORS.courtLines, 0.9, 0.05);
  root.add(detail);

  // Walls: extruded CAD wall bodies — light sides, dark caps so the plan reads like poché.
  const walls = new THREE.Mesh(
    mergeCapsAndSides(model.walls.map((p) => extrude(p, H))),
    [new THREE.MeshLambertMaterial({ color: COLORS.wallCap }), new THREE.MeshLambertMaterial({ color: COLORS.wallSide, emissive: 0x4a463f })],
  );
  walls.castShadow = true;
  walls.receiveShadow = true;
  walls.name = 'Walls (FF-01 CAD wall layers)';
  root.add(walls);

  const glass = new THREE.Mesh(
    mergeAll(model.glazing.map((p) => extrude(p, H * 0.92))),
    new THREE.MeshLambertMaterial({ color: COLORS.glass, transparent: true, opacity: 0.38, depthWrite: false }),
  );
  glass.renderOrder = 3;
  glass.name = 'Glazing (FF-01 CAD glazing layers)';
  root.add(glass);

  let selected: string | null = null;
  let hovered: string | null = null;
  const reduceMotion = typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  const flare = new THREE.Color(COLORS.selected);
  const hoverTint = new THREE.Color(COLORS.hovered);

  // Selected room outline: a crisp ember edge on top of the orange floor.
  const outline = new THREE.LineLoop(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0xd35400, depthTest: false, transparent: true }));
  outline.renderOrder = 6;
  outline.visible = false;
  root.add(outline);

  const targetColor = (id: string, mesh: THREE.Mesh) => {
    const base = new THREE.Color(mesh.userData.baseColor as number);
    if (id === selected) return flare.clone();
    if (id === hovered) return base.lerp(hoverTint, 0.65);
    return base;
  };
  let animating = false;
  const applyColors = (instant = false) => {
    for (const [id, mesh] of roomMeshes) {
      mesh.userData.targetColor = targetColor(id, mesh);
      // Hover and selection answer immediately; layer changes cross-fade.
      if (instant || reduceMotion || id === selected || id === hovered) (mesh.material as THREE.MeshLambertMaterial).color.copy(mesh.userData.targetColor);
      mesh.position.y = id === selected ? 0.03 : 0;
    }
    animating = !instant && !reduceMotion;
    const room = selected ? roomById.get(selected) : undefined;
    outline.visible = !!room?.polygon;
    if (room?.polygon) {
      outline.geometry.dispose();
      outline.geometry = new THREE.BufferGeometry().setFromPoints(room.polygon.o.map(([x, z]) => new THREE.Vector3(x, 0.08, z)));
    }
  };

  return {
    root,
    roomMeshes,
    roomById,
    pickables: [...roomMeshes.values()],
    wallTopY: H,
    setRoomColors(colorFor) {
      for (const [id, mesh] of roomMeshes) mesh.userData.baseColor = colorFor(roomById.get(id)!);
      applyColors(false);
    },
    setHighlight(selectedId, hoveredId) {
      selected = selectedId;
      hovered = hoveredId;
      applyColors(false);
    },
    tick(dtMs) {
      if (!animating) return false;
      const k = 1 - Math.exp(-dtMs / 90);
      let pending = false;
      for (const mesh of roomMeshes.values()) {
        const color = (mesh.material as THREE.MeshLambertMaterial).color;
        const target = mesh.userData.targetColor as THREE.Color | undefined;
        if (!target) continue;
        color.lerp(target, k);
        if (Math.abs(color.r - target.r) + Math.abs(color.g - target.g) + Math.abs(color.b - target.b) > 0.004) pending = true;
        else color.copy(target);
      }
      animating = pending;
      return true;
    },
    setDetailVisible(visible) {
      detail.visible = visible;
    },
    dispose() {
      root.traverse((object) => {
        const mesh = object as THREE.Mesh;
        if (mesh.geometry) mesh.geometry.dispose();
        const material = mesh.material;
        if (Array.isArray(material)) material.forEach((m) => m.dispose());
        else if (material) (material as THREE.Material).dispose();
      });
    },
  };
}
